70	        GemmCoord problemShape;
71	        GM_ADDR ptrA;
72	        GM_ADDR ptrB;
73	        GM_ADDR ptrC;
74	    };
75	
76	    static bool CanImplement(const Arguments& args)
77	    {
78	        return true;
79	    }
80	
