82	    {
83	        return 0;
84	    }
85	
86	    static Params ToUnderlyingArguments(const Arguments& args, uint8_t* workspace)
87	    {
88	        LayoutA layoutA = LayoutA::template MakeLayout<ElementA>(args.problemShape.m(), args.problemShape.k());
89	        LayoutB layoutB = LayoutB::template MakeLayout<ElementB>(args.problemShape.k(), args.problemShape.n());
90	        LayoutC layoutC = LayoutC::template MakeLayout<ElementC>(args.problemShape.m(), args.problemShape.n());
91	        Params params{args.problemShape, args.ptrA, layoutA, args.ptrB, layoutB, args.ptrC, layoutC};
92	        return params;
93	    }
94	
95	    // Methods
96	    CATLASS_DEVICE
97	    BasicMatmul()
98	    {}
99	
100	    template <int32_t CORE_TYPE = g_coreType>
101	    CATLASS_DEVICE void operator()(Params const& params);
102	
103	    /// Executes one Matmul
104	    template <>
105	    CATLASS_DEVICE void operator()<AscendC::AIC>(Params const& params)
106	    {
107	        BlockScheduler matmulBlockScheduler(params.problemShape, MakeCoord(L1TileShape::M, L1TileShape::N));
108	        uint32_t coreLoops = matmulBlockScheduler.GetCoreLoops();
109	
110	        Arch::Resource<ArchTag> resource;
111	        BlockMmad blockMmad(resource);
112	
113	        // Represent the full gm
114	        AscendC::GlobalTensor<ElementA> gmA;
115	        gmA.SetGlobalBuffer((__gm__ ElementA*)params.ptrA);
116	        AscendC::GlobalTensor<ElementB> gmB;
117	        gmB.SetGlobalBuffer((__gm__ ElementB*)params.ptrB);
118	        AscendC::GlobalTensor<ElementC> gmC;
119	        gmC.SetGlobalBuffer((__gm__ ElementC*)params.ptrC);
120	
121	        for (uint32_t loopIdx = AscendC::GetBlockIdx(); loopIdx < coreLoops; loopIdx += AscendC::GetBlockNum()) {
122	            // Compute block location
123	            GemmCoord blockCoord = matmulBlockScheduler.GetBlockCoord(loopIdx);
124	            GemmCoord actualBlockShape = matmulBlockScheduler.GetActualBlockShape(blockCoord);
125	
126	            // Compute initial location in logical coordinates
127	            MatrixCoord offsetA{blockCoord.m() * L1TileShape::M, blockCoord.k() * L1TileShape::K};
128	            MatrixCoord offsetB{blockCoord.k() * L1TileShape::K, blockCoord.n() * L1TileShape::N};
129	            MatrixCoord offsetC{blockCoord.m() * L1TileShape::M, blockCoord.n() * L1TileShape::N};
130	            int64_t gmOffsetA = params.layoutA.GetOffset(offsetA);
131	            int64_t gmOffsetB = params.layoutB.GetOffset(offsetB);
132	            int64_t gmOffsetC = params.layoutC.GetOffset(offsetC);
133	
134	            // Compute block-scoped matrix multiply-add
135	            blockMmad(
136	                gmA[gmOffsetA], params.layoutA, gmB[gmOffsetB], params.layoutB, gmC[gmOffsetC], params.layoutC,
137	                actualBlockShape);
138	        }
139	
140	        AscendC::PipeBarrier<PIPE_ALL>();
141	    }
142	
143	    template <>
144	    CATLASS_DEVICE void operator()<AscendC::AIV>(Params const& params)
145	    {}
