21	namespace Catlass::Gemm::Kernel {
22	
23	template <class ArchTag_, class ElementAccumulator_, class ElementOut_, uint32_t STAGES, uint32_t COMPUTE_LENGTH>
24	struct SplitkReduceAdd {
25	    using ArchTag = ArchTag_;
26	    using ElementAccumulator = ElementAccumulator_;
27	    using ElementOut = ElementOut_;
28	
29	    CATLASS_DEVICE
30	    SplitkReduceAdd(Arch::Resource<ArchTag>& resource)
31	    {
32	        int64_t bufferOffset = 0;
33	        for (uint32_t i = 0; i < STAGES; i++) {
34	            accumulatorBuffer[i] = resource.ubBuf.template GetBufferByByte<ElementAccumulator>(bufferOffset);
35	            outputBuffer[i] = resource.ubBuf.template GetBufferByByte<ElementOut>(bufferOffset);
36	            bufferOffset += COMPUTE_LENGTH * sizeof(ElementAccumulator);
37	            eventIds[i] = i;
38	        }
39	    }
40	
41	    CATLASS_DEVICE
42	    void operator()(
43	        AscendC::GlobalTensor<ElementOut> const& dst, AscendC::GlobalTensor<ElementAccumulator> const& src,
44	        uint64_t elementCount, uint32_t splitkFactor)
45	    {
46	        for (uint32_t i = 0; i < STAGES; ++i) {
47	            AscendC::SetFlag<AscendC::HardEvent::MTE3_MTE2>(eventIds[i]);
48	        }
49	
50	        constexpr uint32_t ELE_NUM_ALIGN = BYTE_PER_BLK / sizeof(ElementOut);
51	        constexpr uint32_t ELE_PER_VECTOR_BLOCK = 256 / sizeof(ElementAccumulator);
52	        uint32_t aivNum = AscendC::GetBlockNum() * AscendC::GetSubBlockNum();
53	        uint32_t aivId = AscendC::GetBlockIdx();
54	
55	        uint64_t taskPerAiv =
56	            (elementCount / aivNum + ELE_PER_VECTOR_BLOCK - 1) / ELE_PER_VECTOR_BLOCK * ELE_PER_VECTOR_BLOCK;
57	        if (taskPerAiv == 0)
58	            taskPerAiv = ELE_PER_VECTOR_BLOCK;
59	
60	        uint32_t taskPerAivMax = COMPUTE_LENGTH / splitkFactor / ELE_PER_VECTOR_BLOCK * ELE_PER_VECTOR_BLOCK;
61	
62	        if (taskPerAiv > taskPerAivMax) {
63	            taskPerAiv = taskPerAivMax;
64	        }
65	
66	        uint32_t loops = (elementCount + taskPerAiv - 1) / taskPerAiv;
67	        for (uint32_t loopIdx = aivId; loopIdx < loops; loopIdx += aivNum) {
68	            uint32_t actualTileLen = taskPerAiv;
69	            if (loopIdx == loops - 1) {
70	                actualTileLen = elementCount - static_cast<uint64_t>(loopIdx) * taskPerAiv;
71	            }
72	
73	            AscendC::WaitFlag<AscendC::HardEvent::MTE3_MTE2>(eventIds[bufferIndex]);
74	            uint64_t srcOffset = static_cast<uint64_t>(loopIdx) * taskPerAiv;
75	            AscendC::DataCopyPadExtParams<ElementAccumulator> padParams(false, 0, 0, 0);
76	            if (elementCount < 4294977295U / sizeof(ElementAccumulator)) {
77	                AscendC::DataCopyExtParams dataCopyParams(
78	                    splitkFactor, actualTileLen * sizeof(ElementAccumulator),
79	                    (elementCount - actualTileLen) * sizeof(ElementAccumulator),
80	                    (RoundUp(actualTileLen, ELE_NUM_ALIGN) - actualTileLen) * sizeof(ElementAccumulator) / BYTE_PER_BLK,
81	                    0);
82	                AscendC::DataCopyPad(accumulatorBuffer[bufferIndex], src[srcOffset], dataCopyParams, padParams);
83	            } else {
84	                for (uint32_t i = 0; i < splitkFactor; ++i) {
85	                    AscendC::DataCopyExtParams dataCopyParams(1, actualTileLen * sizeof(ElementAccumulator), 0, 0, 0);
86	                    AscendC::DataCopyPad(
87	                        accumulatorBuffer[bufferIndex][i * RoundUp(actualTileLen, ELE_NUM_ALIGN)],
88	                        src[srcOffset + i * elementCount], dataCopyParams, padParams);
89	                }
90	            }
91	
92	            AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(eventIds[bufferIndex]);
93	            AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(eventIds[bufferIndex]);
94	
95	            uint64_t offset = 0;
96	            for (uint32_t sliceIdx = 1; sliceIdx < splitkFactor; ++sliceIdx) {
97	                offset = RoundUp(actualTileLen, ELE_NUM_ALIGN) * sliceIdx;
98	                AscendC::Add(
99	                    accumulatorBuffer[bufferIndex][0], accumulatorBuffer[bufferIndex][0],
100	                    accumulatorBuffer[bufferIndex][offset], actualTileLen);
101	                AscendC::PipeBarrier<PIPE_V>();
102	            }
103	
104	            if constexpr (!std::is_same_v<ElementAccumulator, ElementOut>) {
105	                if constexpr (std::is_same_v<ElementOut, half>) {
106	                    AscendC::Cast(
107	                        outputBuffer[bufferIndex], accumulatorBuffer[bufferIndex], AscendC::RoundMode::CAST_NONE,
108	                        actualTileLen);
109	                } else {
110	                    AscendC::Cast(
111	                        outputBuffer[bufferIndex], accumulatorBuffer[bufferIndex], AscendC::RoundMode::CAST_RINT,
112	                        actualTileLen);
113	                }
114	            }
115	
116	            AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(eventIds[bufferIndex]);
117	            AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(eventIds[bufferIndex]);
118	
119	            uint64_t dstOffset = static_cast<uint64_t>(loopIdx) * taskPerAiv;
120	            AscendC::DataCopyExtParams dataCopyParams(1, actualTileLen * sizeof(ElementOut), 0, 0, 0);
121	            AscendC::DataCopyPad(dst[dstOffset], outputBuffer[bufferIndex], dataCopyParams);
122	
123	            AscendC::SetFlag<AscendC::HardEvent::MTE3_MTE2>(eventIds[bufferIndex]);
124	
125	            bufferIndex = (bufferIndex + 1) % STAGES;
126	        }
127	
128	        for (uint32_t i = 0; i < STAGES; ++i) {
129	            AscendC::WaitFlag<AscendC::HardEvent::MTE3_MTE2>(eventIds[i]);
130	        }
131	    }
132	
133	private:
134	    AscendC::LocalTensor<ElementAccumulator> accumulatorBuffer[STAGES];
135	    AscendC::LocalTensor<ElementOut> outputBuffer[STAGES];
136	    AscendC::TEventID eventIds[STAGES];
137	    uint32_t bufferIndex{0};
138	    static_assert(STAGES * COMPUTE_LENGTH * sizeof(ElementAccumulator) <= ArchTag::UB_SIZE, "Excedding the UB space!");
139	};
140	
141	// Template for Matmul kernel. Compute C = A * B
142	template <class BlockMmad_, class BlockEpilogue_, class BlockScheduler_, class ReduceAdd_>
143	class SplitkMatmul {
144	public:
145	    using BlockMmad = BlockMmad_;
146	    using ArchTag = typename BlockMmad::ArchTag;
147	    using L1TileShape = typename BlockMmad::L1TileShape;
148	    using ElementA = typename BlockMmad::ElementA;
149	    using LayoutA = typename BlockMmad::LayoutA;
150	    using ElementB = typename BlockMmad::ElementB;
151	    using LayoutB = typename BlockMmad::LayoutB;
152	    using ElementC = typename BlockMmad::ElementC;
153	    using LayoutC = typename BlockMmad::LayoutC;
154	    using ElementAccumulator = typename BlockMmad::ElementAccumulator;
155	
156	    using BlockScheduler = BlockScheduler_;
157	    using ReduceAdd = ReduceAdd_;
158	
159	    /// Parameters structure
160	    struct Params {
161	        // Data members
162	        GemmCoord problemShape;
163	        GM_ADDR ptrA;
164	        LayoutA layoutA;
165	        GM_ADDR ptrB;
166	        LayoutB layoutB;
167	        GM_ADDR ptrC;
168	        LayoutC layoutC;
169	        GM_ADDR ptrWorkspace;
170	        uint32_t splitkFactor = 1;
171	
172	        // Methods
173	        CATLASS_HOST_DEVICE
174	        Params()
175	        {}
176	
177	        CATLASS_HOST_DEVICE
178	        Params(
179	            GemmCoord const& problemShape_, GM_ADDR ptrA_, LayoutA layoutA_, GM_ADDR ptrB_, LayoutB layoutB_,
180	            GM_ADDR ptrC_, LayoutC layoutC_, GM_ADDR ptrWorkspace_, uint32_t splitkFactor_)
181	            : problemShape(problemShape_),
182	              ptrA(ptrA_),
183	              layoutA(layoutA_),
184	              ptrB(ptrB_),
185	              layoutB(layoutB_),
186	              ptrC(ptrC_),
187	              layoutC(layoutC_),
188	              ptrWorkspace(ptrWorkspace_),
189	              splitkFactor(splitkFactor_)
190	        {}
191	    };
192	
193	    struct Arguments {
194	        GemmCoord problemShape;
195	        uint32_t aicCoreNum;
196	        size_t workspaceElementSize;
197	        GM_ADDR ptrA;
198	        GM_ADDR ptrB;
199	        GM_ADDR ptrC;
200	    };
201	
202	    static uint32_t GetSplitkFactor(uint32_t m, uint32_t n, uint32_t k, uint32_t aicCoreNum)
203	    {
204	        uint32_t maxSplitkFactor;
205	        if (k <= 1024) {
206	            // When k is less than or equal to 1024, it can be divided into at most 2 parts.
207	            maxSplitkFactor = 2;
208	        } else if (k <= 2048) {
209	            // When k is less than or equal to 2048, it can be divided into at most 4 parts.
210	            maxSplitkFactor = 4;
211	        } else if (k <= 4096) {
212	            // When k is less than or equal to 4096, it can be divided into at most 8 parts.
213	            maxSplitkFactor = 8;
214	        } else {
215	            // else it can be divided into at most 16 parts.
216	            maxSplitkFactor = 16;
217	        }
218	        uint32_t splitkFactor = 1;
219	        uint32_t m0 = L1TileShape::M;
220	        uint32_t n0 = L1TileShape::N;
221	        uint32_t k0 = L1TileShape::K;
222	
223	        uint32_t baseTilesCount = CeilDiv(m, m0) * CeilDiv(n, n0);
224	        splitkFactor =
225	            (aicCoreNum / baseTilesCount < maxSplitkFactor) ? (aicCoreNum / baseTilesCount) : maxSplitkFactor;
226	        // Prevent the split factor form being less than 1
227	        splitkFactor = (splitkFactor > static_cast<uint32_t>(1)) ? splitkFactor : static_cast<uint32_t>(1);
228	        if (baseTilesCount < aicCoreNum) {
229	            while (splitkFactor + 1 <= maxSplitkFactor && CeilDiv(baseTilesCount * splitkFactor, aicCoreNum) >=
230	                                                              CeilDiv(baseTilesCount, aicCoreNum) * splitkFactor) {
231	                splitkFactor += 1;
232	            }
233	        }
234	        // Ensure that splitkFactor is less than the number of base tiels in the k direction.
235	        splitkFactor = (CeilDiv(k, k0) < splitkFactor) ? CeilDiv(k, k0) : splitkFactor;
236	        // If k is very large, splitting k can lead to better cache utilization.
237	        // If k is greater than 8192.
238	        if (k > 8192) {
239	            // split the k direction into at least 2 parts.
240	            splitkFactor = (splitkFactor > static_cast<uint32_t>(2)) ? splitkFactor : static_cast<uint32_t>(2);
241	        }
242	        // If k is greater than 32768.
243	        if (k > 32768) {
244	            // split the k direction into at least 4 parts.
245	            splitkFactor = (splitkFactor > static_cast<uint32_t>(4)) ? splitkFactor : static_cast<uint32_t>(4);
246	        }
247	        return splitkFactor;
248	    }
249	
250	    static bool CanImplement(const Arguments& args)
251	    {
252	        return true;
253	    }
254	
255	    static size_t GetWorkspaceSize(const Arguments& args)
256	    {
257	        return static_cast<size_t>(args.workspaceElementSize) * args.problemShape.m() * args.problemShape.n() *
258	               GetSplitkFactor(args.problemShape.m(), args.problemShape.n(), args.problemShape.k(), args.aicCoreNum);
259	    }
260	
261	    static Params ToUnderlyingArguments(const Arguments& args, uint8_t* workspace)
262	    {
263	        LayoutA layoutA = LayoutA::template MakeLayout<ElementA>(args.problemShape.m(), args.problemShape.k());
264	        LayoutB layoutB = LayoutB::template MakeLayout<ElementB>(args.problemShape.k(), args.problemShape.n());
265	        LayoutC layoutC = LayoutC::template MakeLayout<ElementC>(args.problemShape.m(), args.problemShape.n());
266	        Params params{
267	            args.problemShape,
268	            args.ptrA,
269	            layoutA,
270	            args.ptrB,
271	            layoutB,
272	            args.ptrC,
273	            layoutC,
274	            workspace,
275	            GetSplitkFactor(args.problemShape.m(), args.problemShape.n(), args.problemShape.k(), args.aicCoreNum)};
276	        return params;
277	    }
278	
279	    // Methods
280	    CATLASS_DEVICE
281	    SplitkMatmul()
282	    {}
283	
284	    template <int32_t CORE_TYPE = g_coreType>
285	    CATLASS_DEVICE void operator()(Params const& params);
286	
287	    /// Executes one Matmul
288	    template <>
289	    CATLASS_DEVICE void operator()<AscendC::AIC>(Params const& params)
290	    {
291	        BlockScheduler matmulBlockScheduler(
292	            params.problemShape, GemmCoord(L1TileShape::M, L1TileShape::N, L1TileShape::K), params.splitkFactor);
293	        uint32_t coreLoops = matmulBlockScheduler.GetCoreLoops();
294	
295	        Arch::Resource<ArchTag> resource;
296	        BlockMmad blockMmad(resource);
297	
298	        // Represent the full gm
299	        AscendC::GlobalTensor<ElementA> gmA;
300	        gmA.SetGlobalBuffer((__gm__ ElementA*)params.ptrA);
301	        AscendC::GlobalTensor<ElementB> gmB;
302	        gmB.SetGlobalBuffer((__gm__ ElementB*)params.ptrB);
303	        AscendC::GlobalTensor<ElementC> gmC;
304	        gmC.SetGlobalBuffer((__gm__ ElementC*)params.ptrWorkspace);
305	
306	        for (uint32_t loopIdx = AscendC::GetBlockIdx(); loopIdx < coreLoops; loopIdx += AscendC::GetBlockNum()) {
307	            // Compute block location
308	            GemmCoord blockCoord = matmulBlockScheduler.GetBlockCoord(loopIdx);
309	            GemmCoord actualBlockShape =
310	                matmulBlockScheduler.GetActualBlockShape(blockCoord, matmulBlockScheduler.GetSplitkSliceIdx(loopIdx));
311	
312	            // Compute initial location in logical coordinates
313	            MatrixCoord offsetA{blockCoord.m() * L1TileShape::M, blockCoord.k() * L1TileShape::K};
314	            MatrixCoord offsetB{blockCoord.k() * L1TileShape::K, blockCoord.n() * L1TileShape::N};
315	            MatrixCoord offsetC{blockCoord.m() * L1TileShape::M, blockCoord.n() * L1TileShape::N};
316	            uint64_t gmOffsetA = params.layoutA.GetOffset(offsetA);
317	            uint64_t gmOffsetB = params.layoutB.GetOffset(offsetB);
318	            uint64_t gmOffsetC = params.layoutC.GetOffset(offsetC) +
319	                                 static_cast<uint64_t>(params.problemShape.m()) *
320	                                     static_cast<uint64_t>(params.problemShape.n()) *
321	                                     static_cast<uint64_t>(matmulBlockScheduler.GetSplitkSliceIdx(loopIdx));
322	
323	            // Compute block-scoped matrix multiply-add
324	            blockMmad(
325	                gmA[gmOffsetA], params.layoutA, gmB[gmOffsetB], params.layoutB, gmC[gmOffsetC], params.layoutC,
326	                actualBlockShape);
327	        }
328	
329	        Catlass::Arch::CrossCoreSetFlag<0x2, PIPE_FIX>(flagAicFinish);
330	
331	        AscendC::PipeBarrier<PIPE_ALL>();
332	    }
333	
334	    template <>
335	    CATLASS_DEVICE void operator()<AscendC::AIV>(Params const& params)
336	    {
337	        using ElementOut = typename ReduceAdd::ElementOut;
338	        using ElementAccumulator = typename ReduceAdd::ElementAccumulator;
339	
340	        Catlass::Arch::CrossCoreWaitFlag(flagAicFinish);
341	        Catlass::Arch::CrossCoreBarrier<0x0, PIPE_MTE3>();
342	
343	        AscendC::GlobalTensor<ElementOut> gmC;
344	        AscendC::GlobalTensor<ElementAccumulator> gmWorkspace;
345	        gmC.SetGlobalBuffer(reinterpret_cast<__gm__ ElementOut*>(params.ptrC));
346	        gmWorkspace.SetGlobalBuffer(reinterpret_cast<__gm__ ElementAccumulator*>(params.ptrWorkspace));
347	        ReduceAdd reduceAdd(resource);
348	        reduceAdd(
349	            gmC, gmWorkspace,
350	            static_cast<uint64_t>(params.problemShape.m()) * static_cast<uint64_t>(params.problemShape.n()),
351	            params.splitkFactor);
352	
353	        AscendC::PipeBarrier<PIPE_ALL>();
354	    }
355	
356	private:
357	    static constexpr Arch::FlagID FLAG_AIC_FINISH = 0;
358	    Arch::CrossCoreFlag flagAicFinish{FLAG_AIC_FINISH};
359	    Arch::Resource<ArchTag> resource;
360	};
361	
362	} // namespace Catlass::Gemm::Kernel
363	
364	#endif // CATLASS_GEMM_KERNEL_SPLITK_MATMUL_HPP
